def place(r, W, alpha, m):
    """m toppings of width 3 along one row, at least two cheese cells apart."""
    cells = ["~"] * W
    pcs = []
    for i, s in enumerate(sorted(r.sample(range(W + 2 - 4 * m), m))):
        j = s + 4 * i
        L = r.choice(alpha)
        cells[j] = cells[j + 1] = cells[j + 2] = L
        pcs.append((j + 2, L))
    return "##" + "".join(cells) + "##", pcs


def cutb(r, T, n):
    """A uniformly random cutting of a T-wide tray into n slices, each at least 3 wide."""
    b = []
    t = p = 0
    for x in sorted(r.sample(range(T - 2 * n - 1), n - 1)):
        t += x - p + 3
        p = x + 1
        b.append(t)
    return b


def eqb(T, n, m):
    """The three ways a tidy-minded player cuts a T-wide tray into n even slices."""
    if m == 2:
        return [(i * T + n // 2) // n for i in range(1, n)]
    q, e = T // n, T % n
    w = [q + (i < e if m else i >= n - e) for i in range(n)]
    b = []
    t = 0
    for v in w[:-1]:
        t += v
        b.append(t)
    return b


def sums(P, T, alpha):
    """Per letter: how many pieces start by column i, how many have ended by column i."""
    D = {}
    for L in alpha:
        D[L] = ([0] * (T + 4), [0] * (T + 4))
    for c, L in P:
        D[L][0][c] += 1
        D[L][1][c + 3] += 1
    for L in D:
        a, e = D[L]
        s = t = 0
        for i in range(T + 4):
            s += a[i]
            t += e[i]
            a[i] = s
            e[i] = t
    return D


def kof(a, e, b, T):
    """How many slices hold two or more pieces (a halved piece counts on both sides)."""
    lo = k = 0
    for hi in b + [T]:
        if a[hi - 1] - e[lo] > 1:
            k += 1
        lo = hi
    return k


def cnt(D, L, b, T):
    """Pieces of L on each slice (a piece the knife went through counts on both sides)."""
    a, e = D[L]
    out = []
    lo = 0
    for hi in b + [T]:
        out.append(a[hi - 1] - e[lo])
        lo = hi
    return out


def whole(D, L, b, T):
    """Pieces of L lying entirely inside each slice."""
    a, e = D[L]
    out = []
    lo = 0
    for hi in b + [T]:
        out.append(e[hi] - (a[lo - 1] if lo else 0))
        lo = hi
    return out


def shape(P, b, T, x, A):
    """The picture a demo has to show: hand-cut slices of visibly different sizes, and a
    slice holding two pieces of x one of which the knife halved, next to the slice that
    got the other half and nothing else. 2 = that slice holds exactly two, 1 = more."""
    w = [q - p for p, q in zip([0] + b, b + [T])]
    if min(w) > 4 or max(w) - min(w) < 5:
        return 0
    best = 0
    for c, L in P:
        if L != x:
            continue
        i = bisect.bisect_right(b, c)
        j = bisect.bisect_right(b, c + 2)
        if i == j:
            continue
        for p, q in ((i, j), (j, i)):
            if A[p] > 1 and A[q] == 1:
                best = max(best, 2 if A[p] == 2 else 1)
    return best


def ok(D, P, b, T, x, tot, k, A):
    """A cutting that can carry the demo this class lives on: the counted slice holds
    EXACTLY two pieces of x with one of them halved and the neighbour holding just the
    other half (so "slices with two whole pieces" and "slices the topping touches at all"
    can no longer come to k), and the knife has not gone through exactly k pieces of x
    either (v1's trap)."""
    return shape(P, b, T, x, A) == 2 and tot - sum(whole(D, x, b, T)) != k


def generate(seed):
    r = random.Random(seed)
    for _ in range(8):
        W = r.randint(26, 32)                      # one tray size per batch, so the
        T = W + 4                                  # sampled cuttings are drawn once
        nmax = T // 3
        cuts = [cutb(r, T, r.randint(4, nmax)) for _ in range(48)]
        even = [eqb(T, n, m) for n in range(4, nmax + 1) for m in (0, 1, 2)]
        for _ in range(12):
            alpha = r.sample("mpotacsb", 3)
            rows = []
            P = []
            for _ in range(4):
                row, pcs = place(r, W, alpha, 3)
                rows.append(row)
                P += pcs
            cn = {}
            for c, L in P:
                cn[L] = cn.get(L, 0) + 1
            cand = [L for L in alpha if 4 <= cn.get(L, 0) <= 6]
            if not cand:
                continue
            r.shuffle(cand)
            D = sums(P, T, alpha)
            for x in cand:
                a, e = D[x]
                live = {1, 2, 3}
                for b in even:             # equal slices must never be an answer
                    live.discard(kof(a, e, b, T))
                if not live:
                    continue
                hist = {}
                seen = {1: [], 2: [], 3: []}
                for b in cuts:
                    k = kof(a, e, b, T)
                    hist[k] = hist.get(k, 0) + 1
                    if k in live:
                        seen[k].append(b)
                best = [k for k in live if 1 < hist.get(k, 0) < 16]
                best.sort(key=lambda k: hist[k])       # the rarest count that works
                for k in best:
                    for b in seen[k]:
                        if ok(D, P, b, T, x, cn[x], k, cnt(D, x, b, T)):
                            crust = "#" * T
                            return "%s%d\n%s\n%s\n%s" % (x, k, crust,
                                                           "\n".join(rows), crust)
    return ""

