def pcs(rows):
  """Every topping on the tray: (leftmost column, letter). A piece is 3 cells wide."""
  P = []
  for row in rows:
    j = 0
    while j < len(row) - 2:
      c = row[j]
      if c.isalpha() and row[j + 1] == c and row[j + 2] == c:
        P.append((j, c))
        j += 3
      else:
        j += 1
  return P

def cutb(r, T, n):
  """A uniformly random cutting of a T-wide tray into n slices, each at least 3 wide."""
  b = []
  t = p = 0
  for x in sorted(r.sample(range(T - 2 * n - 1), n - 1)):
    t += x - p + 3
    p = x + 1
    b.append(t)
  return b

def sums(P, T, alpha):
  D = {}
  for L in alpha:
    D[L] = ([0] * (T + 4), [0] * (T + 4))
  for c, L in P:
    D[L][0][c] += 1
    D[L][1][c + 3] += 1
  for L in D:
    a, e = D[L]
    s = t = 0
    for i in range(T + 4):
      s += a[i]
      t += e[i]
      a[i] = s
      e[i] = t
  return D

def cnt(D, L, b, T):
  """Pieces of L on each slice; a piece the knife went through counts on both sides."""
  a, e = D[L]
  out = []
  lo = 0
  for hi in b + [T]:
    out.append(a[hi - 1] - e[lo])
    lo = hi
  return out

def whole(D, L, b, T):
  a, e = D[L]
  out = []
  lo = 0
  for hi in b + [T]:
    out.append(e[hi] - (a[lo - 1] if lo else 0))
    lo = hi
  return out

def shape(P, b, T, x, A):
  """Hand-cut slices, and a slice holding two pieces of x one of which the knife halved,
  next to the slice that got the other half and nothing else. 2 = that slice holds exactly
  two (the picture a demo wants), 1 = it holds more, 0 = the demo does not show it."""
  w = [q - p for p, q in zip([0] + b, b + [T])]
  if min(w) > 4 or max(w) - min(w) < 5:
    return 0
  best = 0
  for c, L in P:
    if L != x:
      continue
    i = bisect.bisect_right(b, c)
    j = bisect.bisect_right(b, c + 2)
    if i == j:
      continue
    for p, q in ((i, j), (j, i)):
      if A[p] > 1 and A[q] == 1:
        best = max(best, 2 if A[p] == 2 else 1)
  return best

def grade(D, P, alpha, b, T, x, tot, k, A):
  """0 = a demo that says the whole rule out loud: the picture above (a counted slice with
  exactly two pieces of x, one of them halved, beside the slice holding just the other
  half), a second counted slice holding three so that "exactly two" is visibly not the
  rule, and no rival reading of the cut picture (severed pieces, slices the topping
  touches at all, pairs of whole pieces, pairs of any one topping, the number of cuts)
  coming to k as well. 1 = the same without the slice of three; 2 = a rival survives;
  3 = the counted slice is busier than two; 4 = the picture is not shown at all."""
  h = shape(P, b, T, x, A)
  if not h:
    return 4
  Wh = whole(D, x, b, T)
  if (len(A) - 1 == k or tot - sum(Wh) == k or sum(1 for v in Wh if v > 1) == k
      or sum(1 for v in A if v) == k):
    return 3
  for row in zip(*[cnt(D, L, b, T) for L in alpha]):
    if max(row) > 1:
      k -= 1
  if not k:
    return 2
  return (1 - (max(A) > 2)) if h == 2 else 2

def ren(lines, b):
  out = []
  for row in lines:
    s = ""
    for i, ch in enumerate(row):
      if i in b:
        s += "|"
      s += ch
    out.append(s)
  return "\n".join(out)

def solve(clue):
  a = clue.split("\n")
  x = a[0][0]
  k = int(a[0][1])
  rows = [l for l in a[1:] if "~" in l]
  T = len(rows[0])
  P = pcs(rows)
  alpha = sorted(set(L for c, L in P))
  D = sums(P, T, alpha)
  tot = sum(1 for c, L in P if L == x)
  r = random.Random(clue)
  hold = (9, None)
  for it in range(60000):
    if it > (1500 if hold[0] < 2 else 12000):
      break
    b = cutb(r, T, r.randint(4, T // 3))
    A = cnt(D, x, b, T)
    if sum(1 for v in A if v > 1) != k:
      continue
    g = grade(D, P, alpha, b, T, x, tot, k, A)
    if not g:
      return ren(a[1:], set(b))
    if g < hold[0]:
      hold = (g, b)
  return ren(a[1:], set(hold[1])) if hold[1] else ""

